def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w)
               if len({grid[r][c] for r in range(h)}) == 1)
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    n = min(len(left[0]), len(right[0]))

    def mode(values):
        return max(set(values), key=values.count)

    left_bg = mode([v for row in left for v in row])
    right_bg = mode([v for row in right for v in row])
    return [[3 if left[r][c] == left_bg and right[r][c] == right_bg
             else right_bg for c in range(n)] for r in range(h)]
